    wall = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), h - 1)
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 4 or r == wall:
                continue
            # Each marker falls toward the barrier, then spreads diagonally away from it.
            rest = wall - 1 if r < wall else wall + 1
            for d in range(1, h + 1):
                rr = rest - d if r < wall else rest + d
                if not 0 <= rr < h:
                    break
                for cc in (c - d, c + d):
                    if 0 <= cc < w:
                        out[rr][cc] = 4
            out[rest][c] = 4
    return out

